        static string[] Split(string value)
        {
            string[] parts = value.Split('|');
            if (parts.Length != 16) throw new InvalidOperationException("Browser language vocabulary must contain 16 translations.");
            return parts;
        }

        internal static void Validate(int index)
        {
            if (index < 0 || index >= Codes.Length)
                throw new ArgumentOutOfRangeException("LanguageIndex", "Expected 0..18.");
        }

        internal static int FindCode(string code)
        { return Xiongxin.OWTS.Localization.UiLanguage.FindCode(code); }

        static string BoxLegend(int index)
        {
            return Text(index, "", "Box") + ": Q1–Q3 / " + Text(index, "", "Median") +
                " / " + Text(index, "", "Mean") + " / " + Text(index, "", "Minimum") +
                "–" + Text(index, "", "Maximum");
        }

        internal static string Text(int index, string chinese, string english)
        {
            Validate(index);
            if (index == 0) return chinese;
            if (index == 18) return Xiongxin.OWTS.Localization.UiLanguage.ToTraditional(chinese);
            string localized; if (Xiongxin.OWTS.Localization.UiLanguage.TryTranslate(index, english, out localized)) return localized;
            index = Xiongxin.OWTS.Localization.UiLanguage.LegacyIndex(index);
            if (index == 1) return Xiongxin.OWTS.Localization.UiLanguage.Translate(index, english);
            string[] words;
            if (Words.TryGetValue(english, out words)) return words[index - 2];
            if (english.EndsWith(": ", StringComparison.Ordinal))
            {
                string label = english.Substring(0, english.Length - 2);
                if (Words.ContainsKey(label)) return Text(index, "", label) + ": ";
                if (label == "Statistics records") return Text(index, "", "Statistics") + " " + Text(index, "", "Records") + ": ";
                if (label == "Location file") return Text(index, "", "Location") + " " + Text(index, "", "File") + ": ";
            }
            foreach (string unit in new[] { " / kV", " / pC", " / μs", " / ms", " / V" })
                if (english.EndsWith(unit, StringComparison.Ordinal))
                {
                    string label = english.Substring(0, english.Length - unit.Length);
                    if (label == "Partial Discharge") label = "Discharge";
                    if (Words.ContainsKey(label)) return Text(index, "", label) + unit;
                }
            if (english == "Application sequence" || english == "Application sequence (time order per phase)")
                return Text(index, "", "Test order");
            if (english == "Sample index") return Text(index, "", "Sample point");
            if (english == "Calibration waveform" || english == "Calibration waveform (invalid geometry)")
                return Text(index, "", "Calibration") + " · " + Text(index, "", "Waveform");
            if (english == "Calibration amplitude / V")
                return Text(index, "", "Calibration") + " " + Text(index, "", "Amplitude") + " / V";
            if (english == "Estimated time / ms") return "≈ " + Text(index, "", "Time / ms");
            if (english == "Location waveform")
                return Text(index, "", "Location") + " · " + Text(index, "", "Waveform");
            if (english == "Raw location waveform")
                return Text(index, "", "Raw") + " · " + Text(index, "", "Location") + " · " + Text(index, "", "Waveform");
            if (english.StartsWith("Sequence – voltage", StringComparison.Ordinal))
            {
                string result = Text(index, "", "Test order") + " – " + Text(index, "", "Voltage");
                if (english.Contains("maximum discharge")) result += " – " + Text(index, "", "Maximum discharge");
                else if (english.Contains("tan δ")) result += " – tan δ";
                if (english.Contains("box statistics")) result += " / " + Text(index, "", "Box") + " " + Text(index, "", "Statistics");
                return result;
            }
            if (english.StartsWith("Bar: voltage", StringComparison.Ordinal))
            {
                string result = Text(index, "", "Bar") + ": " + Text(index, "", "Voltage");
                if (english.Contains("maximum PD")) result += "     ●: " + Text(index, "", "Maximum PD");
                if (english.Contains("Box:")) result += "     " + BoxLegend(index);
                if (english.Contains("Line:")) result += "     " + Text(index, "", "Line") + ": tan δ";
                return result;
            }
            if (english.StartsWith("Box: Q1", StringComparison.Ordinal)) return BoxLegend(index);
            return english;
        }
    }

    public sealed partial class ProjectDataBrowserControl
    {
        int languageIndex;

        [Category("Language"), DefaultValue(0)]
        [Description("0=中文, 1=English, 2=Български, 3=Hrvatski, 4=Čeština, 5=Français, 6=Deutsch, 7=Magyar, 8=Italiano, 9=Polski, 10=Română, 11=Русский, 12=Srpski, 13=Slovenčina, 14=Slovenščina, 15=Español, 16=Türkçe, 17=Tiếng Việt")]
        public int LanguageIndex
        {
            get { return languageIndex; }
            set { BrowserLanguages.Validate(value); Ui(() => ChangeLanguage(value)); }
        }

        [Browsable(false)] public string LanguageCode { get { return BrowserLanguages.Codes[languageIndex]; } }
        [Browsable(false)] public string[] AvailableLanguages { get { return GetLanguageNames(); } }
        public string[] GetLanguageNames() { return (string[])LabVIEWItemInformation.UiText.Names.Clone(); }
        public void SetLanguageIndex(int index) { LanguageIndex = index; }
        public void SetEnglishDisplay(bool englishVersion) { EnglishVersion = englishVersion; }
        public bool SetLanguageCode(string code)
        {
            int index = BrowserLanguages.FindCode(code);
            if (index < 0) return false;
            LanguageIndex = index;
            return true;
        }

        void ChangeLanguage(int index)
        {
            if (languageIndex == index) return;
            string oldKind = SelectedNodeKind;
            BrowserRecord record = selectedRecord;
            BrowserWaveform wave = selectedWave;
            int[] nodePath = SelectedTreePath();
            languageIndex = index;
            english = !Xiongxin.OWTS.Localization.UiLanguage.IsChinese(index);
            ApplyLanguage();
            if (project == null || editing || IsBusy)
            {
                if (project == null) SetStatus(T("请先加载项目。", "Load a project to browse its data."));
                return;
            }
            BuildTree();
            TreeNode restored = NodeAtPath(nodePath);
            if (restored != null)
            {
                sync = true;
                tree.SelectedNode = restored;
                sync = false;
            }
            if (oldKind == "project") ShowProjectInfo();
            else if (oldKind.StartsWith("stats", StringComparison.Ordinal)) ShowStatistics(statsMode);
            else if (record != null)
            {
                selectedRecord = record;
                selectedWave = wave;
                SelectedNodeKind = oldKind;
                SelectedFilePath = record.Path;
                if (record.Kind == "loc" && wave != null) RenderLocationWaveform(record, wave);
                else if (wave != null) RenderWave();
                else LoadRecord(record);
            }
            else if (restored != null)
            {
                var data = restored.Tag as NodeData;
                var rows = data == null ? null : data.Value as List<BrowserRecord>;
                if (rows != null) { heading.Text = restored.Text; ShowRecords(rows); }
            }
            SetStatus(T("已显示：", "Displayed: ") + (restored == null ? "" : restored.Text));
        }

        int[] SelectedTreePath()
        {
            var indices = new List<int>();
            for (TreeNode node = tree.SelectedNode; node != null; node = node.Parent)
                indices.Add(node.Index);
            indices.Reverse();
            return indices.ToArray();
        }

        TreeNode NodeAtPath(int[] indices)
        {
            if (indices == null || indices.Length == 0) return null;
            TreeNodeCollection nodes = tree.Nodes;
            TreeNode node = null;
            foreach (int index in indices)
            {
                if (index < 0 || index >= nodes.Count) return null;
                node = nodes[index];
                nodes = node.Nodes;
            }
            return node;
        }
    }
}
